cos = {}
for code, v in C.items():
    if v is None:
        cos[code] = {"skip": SKIP[code], "cyc_pos": "평가 보류", "cycle_note": SKIP[code]}
        continue
    ph, E1, g, r, c, note, w = v
    if code in BULL_IR:
        note += ". 낙관 시나리오는 회사가 IR에서 제시한 중장기 목표(물량·매출)를 대부분 달성하는 경우예요"
    cos[code] = {"E1": E1, "g": {"bear": g[0], "base": g[1], "bull": g[2]}, "r": r, "c": c, "note": note,
                 "nc_adj": False, "cycle": {"phase": ph, "note": "", "w_mid": w, "years": [2020, 2026]}}
for code, t in SKIP.items():
    cos.setdefault(code, {"skip": t, "cyc_pos": "평가 보류", "cycle_note": t})
cfg["companies"] = cos
json.dump(cfg, open(cfg_path, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(len(cos), "개사 가정 저장")
